from openpyxl import load_workbook
wb = load_workbook('/root/data.xlsx', data_only=True)
ws = wb['Data']
# search for cells containing 'Game' or 'Score' or 'List of All Games'
keywords = ['Game', 'Score', 'List of All Games']
found = []
for row in ws.iter_rows():
    for cell in row:
        if isinstance(cell.value, str):
            val = cell.value
            for k in keywords:
                if k.lower() in val.lower():
                    found.append((cell.row, cell.column, val))
                    break

